<template><article v-if="guide" class="article-wrap"><div class="breadcrumbs"><RouterLink to="/">首页</RouterLink><span>/</span><RouterLink to="/guides">攻略指南</RouterLink></div><span class="eyebrow">{{ guide.category }}</span><h1>{{ guide.title }}</h1><p class="article-summary">{{ guide.summary }}</p><div class="article-meta">{{ guide.author }} <span>·</span> {{ guide.publishedAt }} <span>·</span> {{ guide.readTime }}</div><section v-for="section in guide.content" :key="section.heading" class="article-section"><h2>{{ section.heading }}</h2><p v-for="paragraph in section.paragraphs" :key="paragraph">{{ paragraph }}</p></section><div v-if="related.length" class="article-related"><h2>相关游戏</h2><div class="game-grid"><GameCard v-for="g in related" :key="g.id" :game="g"/></div></div><RouterLink to="/guides" class="text-link">← 返回攻略列表</RouterLink></article><div v-else class="empty-state"><h1>文章不存在</h1><RouterLink to="/guides">返回攻略列表</RouterLink></div></template><script setup>import{inject,computed}from'vue';import{useRoute}from'vue-router';import GameCard from '../components/GameCard.vue';const data=inject('siteData'),route=useRoute(),guide=computed(()=>data.guides.find(g=>g.slug===route.params.slug&&g.published)),related=computed(()=>guide.value?.relatedGameIds?.map(id=>data.games.find(g=>g.id===id&&g.published)).filter(Boolean)||[])</script>
